// Characterization tests: pin CURRENT behaviour of order totals, bugs included.
// Pricing is replaced by an in-process double; no network is used.
import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

const prices = { A: 10, B: 25, C: 0.1, D: 33.33, E: 1 }
const pricing = { async priceOf(sku) { return prices[sku] } }

let server, base
before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://localhost:${server.address().port}`
})
after(() => server.close())

const post = (items) => fetch(`${base}/orders`, {
  method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ items }),
})
const totalOf = async (items) => {
  const res = await post(items)
  assert.equal(res.status, 201)
  return (await res.json()).total
}

test('no discount at or below 100', async () => {
  assert.equal(await totalOf([{ sku: 'A', qty: 1 }]), 10)
  assert.equal(await totalOf([{ sku: 'A', qty: 10 }]), 100)
})

test('10% discount applies strictly above 100', async () => {
  assert.equal(await totalOf([{ sku: 'B', qty: 5 }]), 112) // 125 -> 112.5 -> floor
  assert.equal(await totalOf([{ sku: 'A', qty: 20 }]), 180) // 200 -> 180
  assert.equal(await totalOf([{ sku: 'A', qty: 11 }]), 99) // 110 -> 99
})

test('BUG: floating point makes some discounted totals one too low', async () => {
  // 130 * 0.1 = 13.000000000000002, so 130 - that = 116.99999999999999 -> floor 117? pinned below
  const t = await totalOf([{ sku: 'A', qty: 13 }])
  assert.equal(t, 116) // correct value would be 117
  assert.equal(await totalOf([{ sku: 'A', qty: 12 }]), 108) // 120 -> 108 (exact)
})

test('BUG: totals are floored to whole euros, cents are dropped', async () => {
  assert.equal(await totalOf([{ sku: 'D', qty: 1 }]), 33) // 33.33
  assert.equal(await totalOf([{ sku: 'C', qty: 3 }]), 0) // 0.3
})

test('multiple lines are summed before discount', async () => {
  assert.equal(await totalOf([{ sku: 'A', qty: 5 }, { sku: 'B', qty: 3 }]), 112) // 125 -> 112.5
})

test('order is stored and retrievable with the same total', async () => {
  const created = await (await post([{ sku: 'A', qty: 20 }])).json()
  const fetched = await (await fetch(`${base}/orders/${created.id}`)).json()
  assert.deepEqual(fetched, created)
})

test('validation and routing', async () => {
  assert.equal((await post([])).status, 400)
  const missing = await fetch(`${base}/orders/nope`)
  assert.equal(missing.status, 200) // BUG: should be 404
  assert.deepEqual(await missing.json(), { error: 'not found' })
  assert.equal((await fetch(`${base}/nothing`)).status, 404)
})
EOF
